<?php if(!$orders): ?>
<div class="empty"><span><?=mdi('progress-wrench')?></span><h3><?=!empty($q)||!empty($status)?'Servis tidak ditemukan':'Belum ada servis'?></h3><?php if(empty($q)&&empty($status)&&($allowNewService??true)): ?><a class="button" href="<?=e(url('service-new',$newServiceParams??[]))?>"><?=mdi('plus')?> Servis baru</a><?php endif; ?></div>
<?php elseif($user['role']==='customer'): ?>
<div class="service-cards"><?php foreach($orders as $row): ?><article class="service-card"><div class="service-card-top"><span class="device-icon"><?=mdi($row['item_name']==='Laptop'?'laptop':'television')?></span><a class="device-link" href="<?=e(url('order',['id'=>$row['id']]))?>"><h2><?=e($row['item_name'].' '.$row['brand'])?></h2><p><?=e($row['model'])?></p></a><?=badge($row['status'])?></div><div class="service-card-meta"><span><?=e($row['invoice_number'])?></span><time><?=e(human_date($row['received_date']))?></time></div><div class="service-card-bottom"><strong><?=e(money($row['total_cost']))?></strong><a aria-label="Lihat invoice <?=e($row['invoice_number'])?>" href="<?=e(url('invoice',['id'=>$row['id']]))?>">Invoice <?=mdi('arrow-right')?></a></div></article><?php endforeach; ?></div>
<?php else: ?>
<div class="table-scroll"><table><thead><tr><th>INVOICE / TANGGAL</th><th>PERANGKAT</th><th>KONSUMEN</th><th>STATUS</th><th>TOTAL BIAYA</th><th><span class="sr-only">Aksi</span></th></tr></thead><tbody>
<?php foreach($orders as $row): ?><tr><td><a class="table-primary" href="<?=e(url('order',['id'=>$row['id']]))?>"><?=e($row['invoice_number'])?></a><small><?=e(human_date($row['received_date']))?></small></td><td><strong><?=e($row['item_name'])?></strong><small><?=e($row['brand'].' · '.$row['model'])?></small></td><td><strong><?=e($row['customer_name'])?></strong><small><?=e($row['contact_phone'])?></small></td><td><div class="status-cell"><?=badge($row['status'])?><?=status_action($row,true)?></div></td><td class="amount"><?=e(money($row['total_cost']))?></td><td><a class="row-arrow" aria-label="Lihat invoice <?=e($row['invoice_number'])?>" href="<?=e(url(($page??'')==='invoices'?'invoice':'order',['id'=>$row['id']]))?>"><?=mdi('arrow-right')?></a><?php if(($page??'')==='invoices'): ?> <a class="button danger-outline" aria-label="Hapus invoice <?=e($row['invoice_number'])?>" href="<?=e(url('invoice-delete',['id'=>$row['id']]))?>"><?=mdi('delete-outline')?> Hapus</a><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
